#include "base/platform_file.h"
#include "base/process.h"
#include "ipc/ipc_platform_file.h"

IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
    HANDLE target_handle = INVALID_HANDLE_VALUE;
    if (DuplicateHandle(GetCurrentProcess(), handle, process, &target_handle, 0, FALSE, close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return IPC::PlatformFileForTransit(target_handle);
    }
#else
    base::PlatformFile new_handle = base::kInvalidPlatformFileValue;
    if (handle != base::kInvalidPlatformFileValue) {
        new_handle = handle;
        // POSIX: Reuse the handle, as it is already duplicated implicitly by the OS.
    }
    return IPC::PlatformFileForTransit(new_handle);
#endif

    return IPC::PlatformFileForTransit();
}

#include "base/process.h"
#include "base/platform_file.h"
#include "ipc/ipc_platform_file.h"

IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
  HANDLE dup_handle = INVALID_HANDLE_VALUE;
  if (DuplicateHandle(GetCurrentProcess(), handle, process, &dup_handle, 0, FALSE, (close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0) | DUPLICATE_SAME_ACCESS)) {
    return IPC::PlatformFileForTransit(dup_handle);
  }
#else
  int dup_fd = fcntl(handle, F_DUPFD_CLOEXEC, 0);
  if (dup_fd != -1) {
    if (close_source_handle) {
      close(handle);
    }
    return IPC::PlatformFileForTransit(dup_fd);
  }
#endif
  return IPC::PlatformFileForTransit();
}

#include "base/process.h"
#include "base/file.h"
#include "ipc/ipc_platform_file.h"

IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
    HANDLE duplicated_handle = NULL;
    if (!DuplicateHandle(GetCurrentProcess(), handle, process, &duplicated_handle, 0, FALSE, close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return IPC::InvalidPlatformFileForTransit();
    }
    return base::PlatformFileToPlatformFileForTransit(duplicated_handle);
#else
    // On POSIX, we can use the file descriptor directly if it's valid.
    if (handle == base::kInvalidPlatformFile) {
        return IPC::InvalidPlatformFileForTransit();
    }
    return base::PlatformFileToPlatformFileForTransit(handle);
#endif
}

#include "base/process.h"
#include "base/platform_file.h"
#include "ipc/ipc_platform_file.h"

IPC::PlatformFileForTransit DuplicatePlatformFileHandle(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
    HANDLE duplicate_handle = NULL;
    if (!DuplicateHandle(GetCurrentProcess(), handle, process, &duplicate_handle, 0, FALSE, close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return IPC::InvalidPlatformFileForTransit();
    }
    return IPC::PlatformFileForTransit(duplicate_handle);
#else
    int flags = fcntl(handle, F_GETFD);
    if (flags == -1) {
        return IPC::InvalidPlatformFileForTransit();
    }

    if (close_source_handle) {
        flags |= FD_CLOEXEC;
    } else {
        flags &= ~FD_CLOEXEC;
    }

    if (fcntl(handle, F_SETFD, flags) == -1) {
        return IPC::InvalidPlatformFileForTransit();
    }

    return IPC::PlatformFileForTransit(handle);
#endif
}

#include "base/process.h"
#include "base/platform_file.h"
#include "ipc/ipc_export.h"

IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
    HANDLE target_handle;
    if (!DuplicateHandle(GetCurrentProcess(), handle, process, &target_handle, 0, FALSE, close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return base::kInvalidPlatformFileForTransit;
    }
    return base::PlatformFileToPlatformFileForTransit(target_handle);
#elif defined(OS_POSIX)
    // On POSIX, we can just pass the file descriptor directly. It will be closed automatically
    // when it is sent via IPC, so no need to close it now unless requested.
    return base::PlatformFileToPlatformFileForTransit(handle);
#else
#error "Unsupported platform"
#endif
}
